const wire=Data.fromBase64String(String.raw`￼`.replace(/\s/g,''));
if(!wire)throw new Error('学习工具传输内容损坏，未修改原始文件。');
const text=wire.toRawString();
if(typeof text!=='string')throw new Error('学习工具传输内容不是 UTF-8 文本。');
const tracker=importModule('StudyTracker V3');
const result=await tracker.recordEvent(text);
Script.setShortcutOutput(result);
Script.complete();

